import * as fs from 'fs';
import { URL } from 'url';
import * as path from 'path';
import { AbortController } from './abort-controller';

import {
  BackendFactory,
  GetNextJobOptions,
  IoredisListener,
  IQueueBackend,
  JobJson,
  LockManagerWorkerContext,
  Span,
  WorkerOptions,
} from '../interfaces';
import { ConnectionOptions } from '../interfaces/redis-options';
import type { DefaultQueueOptions } from '../types/default-queue-options';
import { JobProgress, JobSchedulerJobOptions } from '../types';
import { Processor } from '../types/processor';
import {
  delay,
  DELAY_TIME_1,
  forwardConnectionError,
  isNotConnectionError,
  randomUUID,
  withDetachedContext,
} from '../utils';
import { QueueBase } from './queue-base';
import { RedisQueueBackend } from './redis-queue-backend';
import { ChildPool } from './child-pool';
import { Job } from './job';
import sandbox from './sandbox';
import { AsyncFifoQueue } from './async-fifo-queue';
import {
  DelayedError,
  RateLimitError,
  RATE_LIMIT_ERROR,
  WaitingChildrenError,
  WaitingError,
  UnrecoverableError,
} from './errors';
import { SpanKind, TelemetryAttributes } from '../enums';
import {
  getLegacyRepeatableJobError,
  hasLegacyRepeatableKeyShape,
  JobScheduler,
} from './job-scheduler';
import { LockManager } from './lock-manager';
import type { NoInferType } from '../types/no-infer';

// 10 seconds is the maximum time a BZPOPMIN can block, so it is the default
// ceiling used when a backend does not delegate its own `maximumBlockTimeout`.
const defaultMaximumBlockTimeout = 10;

// note: sandboxed processors would also like to define concurrency per process
// for better resource utilization.

export interface WorkerListener<
  DataType = any,
  ResultType = any,
  NameType extends string = string,
  ProgressType extends JobProgress = JobProgress,
> extends IoredisListener {
  /**
   * Listen to 'active' event.
   *
   * This event is triggered when a job enters the 'active' state.
   */
  active: (
    job: Job<DataType, ResultType, NameType, ProgressType>,
    prev: string,
  ) => void;

  /**
   * Listen to 'closed' event.
   *
   * This event is triggered when the worker is closed.
   */
  closed: () => void;

  /**
   * Listen to 'closing' event.
   *
   * This event is triggered when the worker is closing.
   */
  closing: (msg: string) => void;

  /**
   * Listen to 'completed' event.
   *
   * This event is triggered when a job has successfully completed.
   */
  completed: (
    job: Job<DataType, ResultType, NameType, ProgressType>,
    result: ResultType,
    prev: string,
  ) => void;

  /**
   * Listen to 'drained' event.
   *
   * This event is triggered when the queue has drained the waiting list.
   * Note that there could still be delayed jobs waiting their timers to expire
   * and this event will still be triggered as long as the waiting list has emptied.
   */
  drained: () => void;

  /**
   * Listen to 'error' event.
   *
   * This event is triggered when an error is throw.
   */
  error: (failedReason: Error) => void;

  /**
   * Listen to 'failed' event.
   *
   * This event is triggered when a job has thrown an exception.
   * Note: job parameter could be received as undefined when an stalled job
   * reaches the stalled limit and it is deleted by the removeOnFail option.
   */
  failed: (
    job: Job<DataType, ResultType, NameType, ProgressType> | undefined,
    error: Error,
    prev: string,
  ) => void;

  /**
   * Listen to 'paused' event.
   *
   * This event is triggered when the queue is paused.
   */
  paused: () => void;

  /**
   * Listen to 'progress' event.
   *
   * This event is triggered when a job updates it progress, i.e. the
   * Job##updateProgress() method is called. This is useful to notify
   * progress or any other data from within a processor to the rest of the
   * world.
   */
  progress: (
    job: Job<DataType, ResultType, NameType, ProgressType>,
    progress: ProgressType,
  ) => void;

  /**
   * Listen to 'ready' event.
   *
   * This event is triggered when blockingConnection is ready.
   */
  ready: () => void;

  /**
   * Listen to 'resumed' event.
   *
   * This event is triggered when the queue is resumed.
   */
  resumed: () => void;

  /**
   * Listen to 'stalled' event.
   *
   * This event is triggered when a job has stalled and
   * has been moved back to the wait list.
   */
  stalled: (jobId: string, prev: string) => void;

  /**
   * Listen to 'lockRenewalFailed' event.
   *
   * This event is triggered when lock renewal fails for one or more jobs.
   */
  lockRenewalFailed: (jobIds: string[]) => void;

  /**
   * Listen to 'locksRenewed' event.
   *
   * This event is triggered when locks are successfully renewed.
   */
  locksRenewed: (data: { count: number; jobIds: string[] }) => void;
}

/**
 *
 * This class represents a worker that is able to process jobs from the queue.
 * As soon as the class is instantiated and a connection to Redis is established
 * it will start processing jobs.
 *
 * @typeParam DataType - The type of the data that the job will process.
 * @typeParam ResultType - The type of the result of the job.
 * @typeParam NameType - The type of the name of the job.
 * @typeParam B - The queue backend used by this worker.
 * @typeParam ProgressType - The type of the job progress. Defaults to
 * {@link JobProgress}. Must be JSON-serializable, as progress is persisted
 * in the backend.
 *
 */
export class Worker<
  DataType = any,
  ResultType = any,
  NameType extends string = string,
  B extends IQueueBackend = RedisQueueBackend,
  ProgressType extends JobProgress = JobProgress,
  ConnectionOptionsType = ConnectionOptions,
> extends QueueBase<B, ConnectionOptionsType> {
  declare readonly opts: WorkerOptions<ConnectionOptionsType>;
  readonly id: string;

  private abortDelayController: AbortController | null = null;
  private blockUntil = 0;
  private _concurrency: number;
  private childPool: ChildPool;
  private drained = false;
  private limitUntil = 0;
  protected lockManager: LockManager;
  private processorAcceptsSignal = false;

  private stalledCheckStopper?: () => void;
  private stalledCheckerPromise?: Promise<void>;
  // Bumped whenever the currently running stalled-checker loop should be
  // abandoned (e.g. by `pause()`). The loop compares its own captured value
  // against the live counter on every iteration and exits as soon as they
  // diverge, without anyone having to await it.
  private stalledCheckerGeneration = 0;
  private waiting: Promise<number> | null = null;
  /**
   * The fetches and jobs tracked by the running main loop, so that `resume()`
   * can wake it up.
   */
  private mainLoopQueue: AsyncFifoQueue<void | Job<
    DataType,
    ResultType,
    NameType,
    ProgressType
  >> | null = null;

  protected _jobScheduler: JobScheduler<B, ConnectionOptionsType>;

  protected paused: boolean;
  protected processFn: Processor<DataType, ResultType, NameType, ProgressType>;
  protected running = false;
  protected mainLoopRunning: Promise<void> | null = null;

  static RateLimitError(): Error {
    return new RateLimitError();
  }

  constructor(
    name: string,
    processor:
      | string
      | URL
      | null
      | Processor<DataType, ResultType, NameType, ProgressType>
      | undefined,
    opts: WorkerOptions<NoInferType<ConnectionOptionsType>>,
    backendFactory: BackendFactory<B, ConnectionOptionsType>,
  );
  constructor(
    name: string,
    processor:
      | string
      | URL
      | null
      | Processor<DataType, ResultType, NameType, ProgressType>
      | undefined,
    opts: WorkerOptions<NoInferType<ConnectionOptionsType>>,
    backendFactory?: undefined,
  );
  constructor(
    name: string,
    processor?:
      | string
      | URL
      | null
      | Processor<DataType, ResultType, NameType, ProgressType>,
    ...args: DefaultQueueOptions<
      B,
      ConnectionOptionsType,
      RedisQueueBackend,
      WorkerOptions
    >
  );
  constructor(
    name: string,
    processor?:
      | string
      | URL
      | null
      | Processor<DataType, ResultType, NameType, ProgressType>,
    opts?: WorkerOptions<ConnectionOptionsType>,
    backendFactory?: BackendFactory<B, ConnectionOptionsType>,
  ) {
    if (!opts || opts.connection === undefined || opts.connection === null) {
      throw new Error('Worker requires a connection');
    }

    super(
      name,
      {
        drainDelay: 5,
        concurrency: 1,
        lockDuration: 30000,
        maximumRateLimitDelay: 30000,
        maxStalledCount: 1,
        stalledInterval: 30000,
        autorun: true,
        runRetryDelay: 15000,
        ...opts,
        blockingConnection: true,
      },
      backendFactory,
    );

    if (
      typeof this.opts.maxStalledCount !== 'number' ||
      this.opts.maxStalledCount < 0
    ) {
      throw new Error('maxStalledCount must be greater or equal than 0');
    }

    if (
      typeof this.opts.maxStartedAttempts === 'number' &&
      this.opts.maxStartedAttempts < 0
    ) {
      throw new Error('maxStartedAttempts must be greater or equal than 0');
    }

    if (
      typeof this.opts.stalledInterval !== 'number' ||
      this.opts.stalledInterval <= 0
    ) {
      throw new Error('stalledInterval must be greater than 0');
    }

    if (typeof this.opts.drainDelay !== 'number' || this.opts.drainDelay <= 0) {
      throw new Error('drainDelay must be greater than 0');
    }

    this.concurrency = this.opts.concurrency;

    this.opts.lockRenewTime =
      this.opts.lockRenewTime || this.opts.lockDuration / 2;

    this.id = randomUUID();

    this.createLockManager();

    if (processor) {
      if (typeof processor === 'function') {
        this.processFn = processor;
        // Check if processor accepts signal parameter (3rd parameter)
        this.processorAcceptsSignal = processor.length >= 3;
      } else {
        // SANDBOXED
        if (processor instanceof URL) {
          if (!fs.existsSync(processor)) {
            throw new Error(
              `URL ${processor} does not exist in the local file system`,
            );
          }
          processor = processor.href;
        } else {
          const supportedFileTypes = ['.js', '.ts', '.flow', '.cjs', '.mjs'];
          const processorFile =
            processor +
            (supportedFileTypes.includes(path.extname(processor)) ? '' : '.js');

          if (!fs.existsSync(processorFile)) {
            throw new Error(`File ${processorFile} does not exist`);
          }
        }

        // Separate paths so that bundling tools can resolve dependencies easier
        const dirname = path.dirname(module.filename || __filename);
        const workerThreadsMainFile = path.join(dirname, 'main-worker.js');
        const spawnProcessMainFile = path.join(dirname, 'main.js');

        let mainFilePath = this.opts.useWorkerThreads
          ? workerThreadsMainFile
          : spawnProcessMainFile;

        try {
          fs.statSync(mainFilePath); // would throw if file not exists
        } catch (_) {
          const mainFile = this.opts.useWorkerThreads
            ? 'main-worker.js'
            : 'main.js';
          mainFilePath = path.join(
            process.cwd(),
            `dist/cjs/classes/${mainFile}`,
          );
          fs.statSync(mainFilePath);
        }

        this.childPool = new ChildPool({
          mainFile: mainFilePath,
          useWorkerThreads: this.opts.useWorkerThreads,
          workerForkOptions: this.opts.workerForkOptions,
          workerThreadsOptions: this.opts.workerThreadsOptions,
        });

        this.createSandbox(processor);
        this.processorAcceptsSignal = true;
      }

      if (this.opts.autorun) {
        this.run().catch(error => this.emit('error', error));
      }
    }

    // The Worker is only "ready" once its dedicated blocking connection (used
    // by the blocking `waitForJob` primitive) is ready. The backend forwards a
    // 'ready' event from *either* of its connections, so we cannot rely on that
    // event to gate on blocking readiness. Instead emit a single 'ready' once
    // `backend.waitUntilReady()` resolves, which only happens after both the
    // main and the blocking connections are ready. Connection failures are
    // surfaced via the 'error' event wired up in QueueBase.
    this.backend
      .waitUntilReady()
      .then(() => setTimeout(() => this.emit('ready'), 0))
      .catch(() => {});
  }

  /**
   * Builds the worker's backend, which owns both the regular connection and a
   * dedicated blocking connection used by the `waitForJob` primitive.
   */
  protected createBackend(): void {
    this.backend = this.backendFactory(this.name, this.opts, {
      withBlockingConnection: true,
    });
  }

  /**
   * Creates and configures the lock manager for processing jobs.
   * This method can be overridden in subclasses to customize lock manager behavior.
   */
  protected createLockManager() {
    this.lockManager = new LockManager(this as LockManagerWorkerContext, {
      lockRenewTime: this.opts.lockRenewTime,
      lockDuration: this.opts.lockDuration,
      workerId: this.id,
      workerName: this.opts.name,
    });
  }

  /**
   * Creates and configures the sandbox for processing jobs.
   * This method can be overridden in subclasses to customize sandbox behavior.
   *
   * @param processor - The processor file path, URL, or function to be sandboxed
   */
  protected createSandbox(
    processor: string | URL | null | Processor<DataType, ResultType, NameType>,
  ) {
    this.processFn = sandbox<DataType, ResultType, NameType>(
      processor,
      this.childPool,
    ).bind(this);
  }

  /**
   * Public accessor method for LockManager to extend locks.
   * This delegates to the protected scripts object.
   */
  async extendJobLocks(
    jobIds: string[],
    tokens: string[],
    duration: number,
  ): Promise<string[]> {
    return this.backend.extendLocks(jobIds, tokens, duration);
  }

  emit<
    U extends keyof WorkerListener<
      DataType,
      ResultType,
      NameType,
      ProgressType
    >,
  >(
    event: U,
    ...args: Parameters<
      WorkerListener<DataType, ResultType, NameType, ProgressType>[U]
    >
  ): boolean {
    return super.emit(event, ...args);
  }

  off<
    U extends keyof WorkerListener<
      DataType,
      ResultType,
      NameType,
      ProgressType
    >,
  >(
    eventName: U,
    listener: WorkerListener<DataType, ResultType, NameType, ProgressType>[U],
  ): this {
    super.off(eventName, listener);
    return this;
  }

  on<
    U extends keyof WorkerListener<
      DataType,
      ResultType,
      NameType,
      ProgressType
    >,
  >(
    event: U,
    listener: WorkerListener<DataType, ResultType, NameType, ProgressType>[U],
  ): this {
    super.on(event, listener);
    return this;
  }

  once<
    U extends keyof WorkerListener<
      DataType,
      ResultType,
      NameType,
      ProgressType
    >,
  >(
    event: U,
    listener: WorkerListener<DataType, ResultType, NameType, ProgressType>[U],
  ): this {
    super.once(event, listener);
    return this;
  }

  protected callProcessJob(
    job: Job<DataType, ResultType, NameType, ProgressType>,
    token: string,
    signal?: AbortSignal,
  ): Promise<ResultType> {
    return this.processFn(job, token, signal);
  }

  protected createJob(
    data: JobJson,
    jobId: string,
  ): Job<DataType, ResultType, NameType, ProgressType> {
    return this.Job.fromJSON(this, data, jobId) as Job<
      DataType,
      ResultType,
      NameType,
      ProgressType
    >;
  }

  /**
   *
   * Waits until the worker is ready to start processing jobs.
   * In general only useful when writing tests.
   *
   */
  async waitUntilReady(): Promise<void> {
    await super.waitUntilReady();
  }

  /**
   * Cancels a specific job currently being processed by this worker.
   * The job's processor function will receive an abort signal.
   *
   * @param jobId - The ID of the job to cancel
   * @param reason - Optional reason for the cancellation
   * @returns true if the job was found and cancelled, false otherwise
   */
  cancelJob(jobId: string, reason?: string): boolean {
    return this.lockManager.cancelJob(jobId, reason);
  }

  /**
   * Cancels all jobs currently being processed by this worker.
   * All active job processor functions will receive abort signals.
   *
   * @param reason - Optional reason for the cancellation
   */
  cancelAllJobs(reason?: string): void {
    this.lockManager.cancelAllJobs(reason);
  }

  set concurrency(concurrency: number) {
    if (
      typeof concurrency !== 'number' ||
      concurrency < 1 ||
      !isFinite(concurrency)
    ) {
      throw new Error('concurrency must be a finite number greater than 0');
    }
    this._concurrency = concurrency;
  }

  get concurrency() {
    return this._concurrency;
  }

  get jobScheduler(): Promise<JobScheduler<B, ConnectionOptionsType>> {
    return new Promise<JobScheduler<B, ConnectionOptionsType>>(
      async resolve => {
        if (!this._jobScheduler) {
          // Share the worker's backend (same queue) with the scheduler.
          this._jobScheduler = new JobScheduler<B, ConnectionOptionsType>(
            this.name,
            this.opts,
            () => this.backend,
          );
          this._jobScheduler.on('error', this.emit.bind(this, 'error'));
        }
        resolve(this._jobScheduler);
      },
    );
  }

  async run() {
    if (!this.processFn) {
      throw new Error('No process function is defined.');
    }

    if (this.running) {
      throw new Error('Worker is already running.');
    }

    try {
      this.running = true;

      if (this.closing || this.paused) {
        return;
      }

      await this.startStalledCheckTimer();

      if (!this.opts.skipLockRenewal) {
        this.lockManager.start();
      }

      this.mainLoopRunning = this.mainLoop();

      // We must await here or finally will be called too early.
      await this.mainLoopRunning;
    } finally {
      this.running = false;
    }
  }

  private async waitForRateLimit(): Promise<void> {
    const limitUntil = this.limitUntil;
    if (limitUntil > Date.now()) {
      this.abortDelayController?.abort();
      this.abortDelayController = new AbortController();

      const delay = this.getRateLimitDelay(limitUntil - Date.now());

      await this.delay(delay, this.abortDelayController);
      this.drained = false;
      this.limitUntil = 0;
    }
  }

  /**
   * This is the main loop in BullMQ. Its goals are to fetch jobs from the queue
   * as efficiently as possible, providing concurrency and minimal unnecessary calls
   * to Redis.
   */
  private async mainLoop() {
    const asyncFifoQueue = new AsyncFifoQueue<void | Job<
      DataType,
      ResultType,
      NameType,
      ProgressType
    >>();
    this.mainLoopQueue = asyncFifoQueue;

    let tokenPostfix = 0;

    while ((!this.closing && !this.paused) || asyncFifoQueue.numTotal() > 0) {
      /**
       * This inner loop tries to fetch jobs concurrently, but if we are waiting for a job
       * to arrive at the queue we should not try to fetch more jobs (as it would be pointless)
       */
      while (
        !this.closing &&
        !this.paused &&
        !this.waiting &&
        asyncFifoQueue.numTotal() < this._concurrency &&
        !this.isRateLimited()
      ) {
        const token = `${this.id}:${tokenPostfix++}`;

        const fetchedJob = this.retryIfFailed<void | Job<
          DataType,
          ResultType,
          NameType,
          ProgressType
        >>(() => this._getNextJob(token, { block: true }), {
          delayInMs: this.opts.runRetryDelay,
          onlyEmitError: true,
        });
        asyncFifoQueue.add(fetchedJob);

        if (this.waiting && asyncFifoQueue.numTotal() > 1) {
          // We are waiting for jobs but we have others that we could start processing already
          break;
        }

        // We await here so that we fetch jobs in sequence, this is important to avoid unnecessary calls
        // to Redis in high concurrency scenarios.
        const job = await fetchedJob;

        // No more jobs waiting but we have others that could start processing already
        if (!job && asyncFifoQueue.numTotal() > 1) {
          break;
        }

        // If there are potential jobs to be processed and blockUntil is set, we should exit to avoid waiting
        // for processing this job.
        if (this.blockUntil) {
          break;
        }
      }

      // Since there can be undefined jobs in the queue (when a job fails or queue is empty)
      // we iterate until we find a job.
      let job: Job<DataType, ResultType, NameType, ProgressType> | void;
      do {
        job = await asyncFifoQueue.fetch();
      } while (!job && asyncFifoQueue.numQueued() > 0);

      if (job) {
        const token = job.token;
        asyncFifoQueue.add(
          this.processJob(
            <Job<DataType, ResultType, NameType, ProgressType>>job,
            token,
            () => asyncFifoQueue.numTotal() <= this._concurrency,
          ),
        );
      } else if (asyncFifoQueue.numQueued() === 0) {
        await this.waitForRateLimit();
      }
    }

    if (this.mainLoopQueue === asyncFifoQueue) {
      this.mainLoopQueue = null;
    }
  }

  /**
   * Returns a promise that resolves to the next job in queue.
   * @param token - worker token to be assigned to retrieved job
   * @returns a Job or undefined if no job was available in the queue.
   */
  async getNextJob(token: string, { block = true }: GetNextJobOptions = {}) {
    const nextJob = await this._getNextJob(token, { block });

    return this.trace<
      Job<DataType, ResultType, NameType, ProgressType> | undefined
    >(
      SpanKind.INTERNAL,
      'getNextJob',
      this.name,
      async span => {
        span?.setAttributes({
          [TelemetryAttributes.WorkerId]: this.id,
          [TelemetryAttributes.QueueName]: this.name,
          [TelemetryAttributes.WorkerName]: this.opts.name,
          [TelemetryAttributes.WorkerOptions]: JSON.stringify({ block }),
          [TelemetryAttributes.JobId]: nextJob?.id,
        });

        return nextJob;
      },
      nextJob?.opts?.telemetry?.metadata,
    );
  }

  private async _getNextJob(
    token: string,
    { block = true }: GetNextJobOptions = {},
  ): Promise<Job<DataType, ResultType, NameType, ProgressType> | undefined> {
    if (this.paused) {
      return;
    }

    if (this.closing) {
      return;
    }

    let job: Job<DataType, ResultType, NameType, ProgressType> | undefined;
    if (this.drained && block && !this.limitUntil && !this.waiting) {
      this.waiting = this.waitForJob(this.blockUntil);
      try {
        this.blockUntil = await this.waiting;

        if (this.blockUntil <= 0 || this.blockUntil - Date.now() < 1) {
          job = await this.moveToActive(token, this.opts.name);
        }
      } finally {
        this.waiting = null;
      }
    } else {
      if (!this.isRateLimited()) {
        job = await this.moveToActive(token, this.opts.name);
      }
    }

    return job;
  }

  /**
   * Overrides the rate limit to be active for the next jobs.
   * @deprecated This method is deprecated and will be removed in v6. Use queue.rateLimit method instead.
   * @param expireTimeMs - expire time in ms of this rate limit.
   */
  async rateLimit(expireTimeMs: number): Promise<void> {
    await this.trace<void>(
      SpanKind.INTERNAL,
      'rateLimit',
      this.name,
      async span => {
        span?.setAttributes({
          [TelemetryAttributes.WorkerId]: this.id,
          [TelemetryAttributes.WorkerRateLimit]: expireTimeMs,
        });

        await this.backend.setRateLimit(expireTimeMs);
      },
    );
  }

  get minimumBlockTimeout(): number {
    return this.backend.minimumBlockTimeout;
  }

  get maximumBlockTimeout(): number {
    return this.backend.maximumBlockTimeout ?? defaultMaximumBlockTimeout;
  }

  private isRateLimited(): boolean {
    return this.limitUntil > Date.now();
  }

  protected async moveToActive(
    token: string,
    name?: string,
  ): Promise<Job<DataType, ResultType, NameType, ProgressType>> {
    const [jobData, id, rateLimitDelay, delayUntil] =
      await this.backend.moveToActive(token, name);
    this.updateDelays(rateLimitDelay, delayUntil);

    return this.nextJobFromJobData(jobData, id, token);
  }

  private async waitForJob(blockUntil: number): Promise<number> {
    if (this.paused) {
      return Infinity;
    }

    try {
      if (!this.closing && !this.isRateLimited()) {
        const blockTimeout = this.getBlockTimeout(blockUntil);

        if (blockTimeout > 0) {
          this.updateDelays(); // reset delays to avoid reusing same values in next iteration

          // Markers should only be used for un-blocking, so we will handle them
          // in this function only. Capability-based timeout rounding and the
          // stuck-connection watchdog are owned by the backend's waitForJob.
          const result = await this.backend.waitForJob(blockTimeout);
          if (result) {
            const newBlockUntil = result.score;
            // Use by pro version as rate limited groups could generate lower blockUntil values
            // markers only return delays for delayed jobs
            if (blockUntil && newBlockUntil > blockUntil) {
              return blockUntil;
            }
            return newBlockUntil;
          }
        }

        return 0;
      }
    } catch (error) {
      if (isNotConnectionError(<Error>error)) {
        this.emit('error', <Error>error);
      }
      // The watchdog must abort every overdue blocking command, but doing so
      // during socketless Sentinel resolution can leave the blocking transport
      // disconnected. Ask the backend to recover it before retrying.
      if (!this.closing) {
        try {
          await this.backend.reconnectBlocking();
        } catch (reconnectError) {
          if (isNotConnectionError(<Error>reconnectError)) {
            this.emit('error', <Error>reconnectError);
          }
        }
      }
      if (!this.closing) {
        await this.delay();
      }
    }
    return Infinity;
  }

  protected getBlockTimeout(blockUntil: number): number {
    const opts = this.opts;

    // when there are delayed jobs
    if (blockUntil) {
      const blockDelay = blockUntil - Date.now();
      // when we reach the time to get new jobs
      if (blockDelay <= 0) {
        return blockDelay;
      } else if (blockDelay < this.minimumBlockTimeout * 1000) {
        return this.minimumBlockTimeout;
      } else {
        // We restrict the maximum block timeout to avoid blocking the
        // connection for too long in the case of reconnections. The ceiling is
        // backend-specific: Redis caps it at 10s (a `BZPOPMIN` blocked longer
        // risks issues on reconnection, see #1658), whereas a backend that
        // keeps the connection open and re-arms to the next due job can allow a
        // much larger value so an idle worker stops re-polling.
        return Math.min(blockDelay / 1000, this.maximumBlockTimeout);
      }
    } else {
      return Math.max(opts.drainDelay, this.minimumBlockTimeout);
    }
  }

  protected getRateLimitDelay(delay: number): number {
    // We restrict the maximum limit delay to the configured maximumRateLimitDelay
    // to be able to promote delayed jobs while the queue is rate limited
    return Math.min(delay, this.opts.maximumRateLimitDelay);
  }

  /**
   *
   * This function is exposed only for testing purposes.
   */
  async delay(
    milliseconds?: number,
    abortController?: AbortController,
  ): Promise<void> {
    await delay(milliseconds || DELAY_TIME_1, abortController);
  }

  private updateDelays(limitDelay = 0, delayUntil = 0) {
    const clampedLimit = Math.max(limitDelay, 0);
    if (clampedLimit > 0) {
      this.limitUntil = Date.now() + clampedLimit;
    } else {
      this.limitUntil = 0;
    }
    this.blockUntil = Math.max(delayUntil, 0) || 0;
  }

  protected async nextJobFromJobData(
    jobData?: JobJson,
    jobId?: string,
    token?: string,
  ): Promise<Job<DataType, ResultType, NameType, ProgressType>> {
    if (!jobData) {
      if (!this.drained) {
        this.emit('drained');
        this.drained = true;
      }
    } else {
      this.drained = false;
      const job = this.createJob(jobData, jobId);
      job.token = token;

      try {
        const shouldScheduleRepeat = await this.retryIfFailed(
          async () => {
            // We need to distinguish between new job schedulers and legacy
            // repeatable jobs. We first use a key-shape heuristic to detect
            // legacy repeat keys (`name:id:endDate:tz:<cron|every>`), then
            // probe the per-id scheduler metadata hash (`repeat:<id>` with
            // the `ic` field) via `JobScheduler.isJobScheduler()` for
            // disambiguation when needed (see issue #3828).
            const hasRepeatJobKey = !!job.repeatJobKey;
            const hasLegacyKeyShape =
              hasRepeatJobKey && hasLegacyRepeatableKeyShape(job.repeatJobKey);
            let isJobScheduler = hasRepeatJobKey && !hasLegacyKeyShape;
            if (hasLegacyKeyShape) {
              const jobScheduler = await this.jobScheduler;
              isJobScheduler = await jobScheduler.isJobScheduler(
                job.repeatJobKey,
              );
            }

            if (isJobScheduler) {
              const jobScheduler = await this.jobScheduler;
              await jobScheduler.upsertJobScheduler(
                // Most of these arguments are not really needed
                // anymore as we read them from the job scheduler itself
                job.repeatJobKey,
                (job.opts as JobSchedulerJobOptions).repeat,
                job.name,
                job.data,
                job.opts,
                { override: false, producerId: job.id },
              );
            }

            return !hasLegacyKeyShape || isJobScheduler;
          },
          { delayInMs: this.opts.runRetryDelay },
        );

        if (job.repeatJobKey && !shouldScheduleRepeat) {
          const schedulingError = new Error(
            `Failed to add repeatable job for next iteration: ${
              getLegacyRepeatableJobError(job.repeatJobKey).message
            }`,
          );
          this.emit('error', schedulingError);
        }
      } catch (err) {
        // Emit error but don't throw to avoid breaking current job completion
        // Note: This means the next repeatable job will not be scheduled
        const errorMessage = err instanceof Error ? err.message : String(err);
        const schedulingError = new Error(
          `Failed to add repeatable job for next iteration: ${errorMessage}`,
        );
        this.emit('error', schedulingError);

        // Return undefined to indicate no next job is available
        return undefined;
      }

      this.emit('active', job, 'waiting');

      return job;
    }
  }

  async processJob(
    job: Job<DataType, ResultType, NameType, ProgressType>,
    token: string,
    fetchNextCallback = () => true,
  ): Promise<void | Job<DataType, ResultType, NameType, ProgressType>> {
    const srcPropagationMetadata = job.opts?.telemetry?.metadata;

    return this.trace<void | Job<DataType, ResultType, NameType, ProgressType>>(
      SpanKind.CONSUMER,
      'process',
      this.name,
      async span => {
        span?.setAttributes({
          [TelemetryAttributes.WorkerId]: this.id,
          [TelemetryAttributes.WorkerName]: this.opts.name,
          [TelemetryAttributes.JobId]: job.id,
          [TelemetryAttributes.JobName]: job.name,
        });

        const abortController = this.lockManager.trackJob(
          job.id,
          token,
          job.processedOn,
          this.processorAcceptsSignal,
        );

        try {
          const unrecoverableErrorMessage =
            this.getUnrecoverableErrorMessage(job);
          if (unrecoverableErrorMessage) {
            const failed = await this.retryIfFailed<void | Job<
              DataType,
              ResultType,
              NameType,
              ProgressType
            >>(
              () => {
                this.lockManager.untrackJob(job.id);
                return this.handleFailed(
                  new UnrecoverableError(unrecoverableErrorMessage),
                  job,
                  token,
                  fetchNextCallback,
                  span,
                );
              },
              { delayInMs: this.opts.runRetryDelay, span },
            );
            return failed;
          }

          const result = await this.callProcessJob(
            job,
            token,
            abortController
              ? (abortController.signal as AbortSignal)
              : undefined,
          );
          return await this.retryIfFailed<void | Job<
            DataType,
            ResultType,
            NameType,
            ProgressType
          >>(
            () => {
              this.lockManager.untrackJob(job.id);
              return this.handleCompleted(
                result,
                job,
                token,
                fetchNextCallback,
                span,
              );
            },
            { delayInMs: this.opts.runRetryDelay, span },
          );
        } catch (err) {
          const failed = await this.retryIfFailed<void | Job<
            DataType,
            ResultType,
            NameType,
            ProgressType
          >>(
            () => {
              this.lockManager.untrackJob(job.id);
              return this.handleFailed(
                <Error>err,
                job,
                token,
                fetchNextCallback,
                span,
              );
            },
            { delayInMs: this.opts.runRetryDelay, span, onlyEmitError: true },
          );
          return failed;
        } finally {
          this.lockManager.untrackJob(job.id);
          const now = Date.now();

          span?.setAttributes({
            [TelemetryAttributes.JobAttemptFinishedTimestamp]:
              job.finishedOn || now,
            [TelemetryAttributes.JobProcessedTimestamp]: job.processedOn,
          });
        }
      },
      srcPropagationMetadata,
    );
  }

  private getUnrecoverableErrorMessage(
    job: Job<DataType, ResultType, NameType, ProgressType>,
  ) {
    if (job.deferredFailure) {
      return job.deferredFailure;
    }
    if (
      this.opts.maxStartedAttempts &&
      this.opts.maxStartedAttempts < job.attemptsStarted
    ) {
      return 'job started more than allowable limit';
    }
  }

  protected async handleCompleted(
    result: ResultType,
    job: Job<DataType, ResultType, NameType, ProgressType>,
    token: string,
    fetchNextCallback = () => true,
    span?: Span,
  ) {
    if (!this.backend.closing) {
      const completed = await job.moveToCompleted(
        result,
        token,
        fetchNextCallback() && !(this.closing || this.paused),
      );
      this.emit('completed', job, result, 'active');

      span?.addEvent('job completed', {
        [TelemetryAttributes.JobResult]: JSON.stringify(result),
      });

      span?.setAttributes({
        [TelemetryAttributes.JobAttemptsMade]: job.attemptsMade,
      });

      if (Array.isArray(completed)) {
        const [jobData, jobId, rateLimitDelay, delayUntil] = completed;
        this.updateDelays(rateLimitDelay, delayUntil);

        return this.nextJobFromJobData(jobData, jobId, token);
      }
    }
  }

  protected async handleFailed(
    err: Error,
    job: Job<DataType, ResultType, NameType, ProgressType>,
    token: string,
    fetchNextCallback = () => true,
    span?: Span,
  ) {
    if (!this.backend.closing) {
      // Check if the job was manually rate-limited
      if (err.message === RATE_LIMIT_ERROR) {
        const rateLimitTtl = await this.moveLimitedBackToWait(job, token);
        this.limitUntil = rateLimitTtl > 0 ? Date.now() + rateLimitTtl : 0;
        return;
      }

      const fetchNext = fetchNextCallback() && !(this.closing || this.paused);
      if (
        err instanceof DelayedError ||
        err.name == 'DelayedError' ||
        err instanceof WaitingError ||
        err.name == 'WaitingError' ||
        err instanceof WaitingChildrenError ||
        err.name == 'WaitingChildrenError'
      ) {
        if (!fetchNext) {
          return;
        }

        return this.moveToActive(token, this.opts.name);
      }

      const result = await job.moveToFailed(err, token, fetchNext);

      this.emit('failed', job, err, 'active');

      span?.addEvent('job failed', {
        [TelemetryAttributes.JobFailedReason]: err.message,
      });
      span?.setAttributes({
        [TelemetryAttributes.JobAttemptsMade]: job.attemptsMade,
      });

      // Note: result can be undefined if moveToFailed fails (e.g., lock was lost)
      if (Array.isArray(result)) {
        const [jobData, jobId, rateLimitDelay, delayUntil] = result;
        this.updateDelays(rateLimitDelay, delayUntil);
        return this.nextJobFromJobData(jobData, jobId, token);
      }
    }
  }

  /**
   *
   * Pauses the processing of this queue only for this worker.
   */
  async pause(doNotWaitActive?: boolean): Promise<void> {
    // Kept in the caller's active context (not detached): a correctly
    // implemented AsyncLocalStorage-based context manager isolates concurrent
    // async chains, so a background stalled-checker tick (which detaches its
    // own context; see `stalledChecker()`) cannot overwrite this span's
    // context. Staying attached lets applications correlate `pause` with the
    // request or operation that initiated it.
    await this.trace<void>(
      SpanKind.INTERNAL,
      'pause',
      this.name,
      async span => {
        span?.setAttributes({
          [TelemetryAttributes.WorkerId]: this.id,
          [TelemetryAttributes.WorkerName]: this.opts.name,
          [TelemetryAttributes.WorkerDoNotWaitActive]: doNotWaitActive,
        });

        if (!this.paused) {
          this.paused = true;
          if (!doNotWaitActive) {
            await this.whenCurrentJobsFinished();
          }
          // Invalidate the currently running stalled-checker loop and cancel
          // its pending timer. This is intentionally fire-and-forget: the
          // loop may be in the middle of an in-flight Redis call (which, on
          // a connection error, retries with its own delay), so awaiting it
          // here could block `pause()` for an unbounded amount of time. The
          // loop itself checks the generation on every iteration and will
          // exit on its own as soon as it next has a chance to.
          this.stalledCheckerGeneration++;
          this.stalledCheckStopper?.();
          this.emit('paused');
        }
      },
    );
  }

  /**
   *
   * Resumes processing of this worker (if paused).
   */
  async resume(): Promise<void> {
    try {
      if (!this.running || this.paused) {
        let restartStalledChecker = false;

        // Kept in the caller's active context for the same reason as
        // `pause()`: only the background stalled-checker loop needs to
        // detach its own context, so it cannot leak into this span.
        await this.trace<void>(
          SpanKind.INTERNAL,
          'resume',
          this.name,
          async span => {
            span?.setAttributes({
              [TelemetryAttributes.WorkerId]: this.id,
              [TelemetryAttributes.WorkerName]: this.opts.name,
            });

            this.paused = false;

            if (!this.running) {
              if (this.processFn) {
                this.run();
              }
            } else {
              // Main loop is still running (pause was called with doNotWaitActive=true).
              // Restart the stalled checker since pause() stopped it.
              restartStalledChecker = true;
              // While paused, the main loop does not fetch new jobs and may only be
              // waiting for the jobs that were already active. Wake it up so that it
              // fetches again without waiting for those jobs to finish.
              this.mainLoopQueue?.add(Promise.resolve());
            }
            this.emit('resumed');
          },
        );

        // Started outside of the trace above so that the stalled checker loop
        // does not inherit the (already ended) `resume` span as its parent.
        if (restartStalledChecker) {
          await this.startStalledCheckTimer();
        }
      }
    } catch (error) {
      this.emit('error', error as Error);
    }
  }

  /**
   *
   * Checks if worker is paused.
   *
   * @returns true if worker is paused, false otherwise.
   */
  isPaused(): boolean {
    return !!this.paused;
  }

  /**
   *
   * Checks if worker is currently running.
   *
   * @returns true if worker is running, false otherwise.
   */
  isRunning(): boolean {
    return this.running;
  }

  /**
   *
   * Closes the worker and related redis connections.
   *
   * This method waits for current jobs to finalize before returning.
   *
   * @param force - Use force boolean parameter if you do not want to wait for
   * current jobs to be processed. When using telemetry, be mindful that it can
   * interfere with the proper closure of spans, potentially preventing them from being exported.
   *
   * @returns Promise that resolves when the worker has been closed.
   */
  async close(force = false): Promise<void> {
    if (this.closing) {
      return this.closing;
    }

    this.closing = (async () => {
      await this.trace<void>(
        SpanKind.INTERNAL,
        'close',
        this.name,
        async span => {
          span?.setAttributes({
            [TelemetryAttributes.WorkerId]: this.id,
            [TelemetryAttributes.WorkerName]: this.opts.name,
            [TelemetryAttributes.WorkerForceClose]: force,
          });
          this.emit('closing', 'closing queue');
          this.abortDelayController?.abort();

          // Define the async cleanup functions
          const asyncCleanups = [
            () => {
              return force || this.whenCurrentJobsFinished(false);
            },
            () => this.lockManager.close(),
            () => this.childPool?.clean(),
            () => this.backend.close(force),
          ];

          // Run cleanup functions sequentially and make sure all are run despite any errors
          for (const cleanup of asyncCleanups) {
            try {
              await cleanup();
            } catch (err) {
              this.emit('error', <Error>err);
            }
          }

          this.stalledCheckStopper?.();

          this.closed = true;
          this.emit('closed');
        },
      );
    })();

    return await this.closing;
  }

  /**
   *
   * Manually starts the stalled checker.
   * The check will run once as soon as this method is called, and
   * then every opts.stalledInterval milliseconds until the worker is closed.
   * Note: Normally you do not need to call this method, since the stalled checker
   * is automatically started when the worker starts processing jobs after
   * calling run. However if you want to process the jobs manually you need
   * to call this method to start the stalled checker.
   *
   * @see {@link https://docs.bullmq.io/patterns/manually-fetching-jobs}
   */
  async startStalledCheckTimer(): Promise<void> {
    if (this.opts.skipStalledCheck) {
      return;
    }

    if (this.closing) {
      return;
    }

    // Claim a new generation for this loop synchronously (before the first
    // await), so that two concurrent callers (e.g. the automatic `run()`
    // startup racing a manual `startStalledCheckTimer()` call, or `resume()`
    // racing a not-yet-finished old loop that `pause()` just invalidated)
    // cannot both end up owning a checker loop: only the call that captures
    // the latest generation value proceeds past the check below.
    const generation = ++this.stalledCheckerGeneration;

    // Capture whatever loop (if any) is still winding down. Bumping the
    // generation above only makes it stop at its next checkpoint; it does
    // not cancel an in-flight `moveStalledJobsToWait` call, so we must let it
    // fully finish before starting a new loop, otherwise both loops could run
    // concurrently and scan for stalled jobs at the same time. This is
    // chained below rather than awaited here in the public call path: an
    // in-flight Redis call can be stuck behind `checkConnectionError`'s retry
    // delay (or a slow reconnect) well after the worker has been paused, and
    // callers such as `resume()` must return promptly instead of blocking on
    // it, exactly like the previous "reuse the still-running checker"
    // behavior used to.
    const previousStalledCheckerPromise = this.stalledCheckerPromise;

    // Wake up the previous loop's pending interval timer (if any) so it can
    // observe the new generation and exit promptly, instead of leaving it to
    // wait out the remainder of its `stalledInterval` wait.
    this.stalledCheckStopper?.();

    await this.trace<void>(
      SpanKind.INTERNAL,
      'startStalledCheckTimer',
      this.name,
      async span => {
        span?.setAttributes({
          [TelemetryAttributes.WorkerId]: this.id,
          [TelemetryAttributes.WorkerName]: this.opts.name,
        });
      },
    );

    // The trace above is asynchronous, so the worker may have been closed, or
    // another call may have claimed a newer generation, while it was in
    // flight.
    if (this.closing || generation !== this.stalledCheckerGeneration) {
      return;
    }

    // Chain the new loop to start only once the previous one has fully
    // exited (its errors are already handled by its own `.catch` below, so
    // swallow them here), guaranteeing the two never scan concurrently -
    // without awaiting that settlement from this public method, so
    // `startStalledCheckTimer()`/`resume()` return promptly regardless of how
    // long the previous loop's in-flight Redis call takes to settle.
    this.stalledCheckerPromise = (
      previousStalledCheckerPromise?.catch((): void => undefined) ??
      Promise.resolve()
    )
      .then(() => {
        // The wait above can take a while (e.g. a connection error retry
        // delay), during which the worker may have closed or yet another
        // caller may have claimed a newer generation.
        if (this.closing || generation !== this.stalledCheckerGeneration) {
          return;
        }

        return withDetachedContext(this.opts.telemetry, () =>
          this.stalledChecker(generation),
        );
      })
      .catch(err => {
        this.emit('error', <Error>err);
      });
  }

  private async stalledChecker(generation: number) {
    // The entire loop (including its recurring interval timer) is started
    // under a detached root context by the caller above. Context managers
    // backed by `AsyncLocalStorage` associate every continuation created
    // inside a callback with whatever context was active when that
    // continuation was created; detaching only the individual Redis call on
    // each tick would still leave the long-lived `setTimeout` chain (and
    // therefore every subsequent tick) parented to the caller's ambient span
    // for the worker's whole lifetime, since a later no-op detached callback
    // cannot retroactively replace a store that AsyncLocalStorage already
    // restored to the outer (caller) context once the initial detached call
    // returned.
    while (
      !(this.closing || this.paused) &&
      generation === this.stalledCheckerGeneration
    ) {
      await this.checkConnectionError(() => this.moveStalledJobsToWait());

      if (
        this.closing ||
        this.paused ||
        generation !== this.stalledCheckerGeneration
      ) {
        break;
      }

      await new Promise<void>(resolve => {
        const timeout = setTimeout(resolve, this.opts.stalledInterval);
        this.stalledCheckStopper = () => {
          clearTimeout(timeout);
          resolve();
        };
      });
    }
  }

  /**
   * Returns a promise that resolves when active jobs are cleared
   *
   * @returns
   */
  private async whenCurrentJobsFinished(reconnect = true) {
    // The blocking connection is dedicated to bzpopmin, so it is safe to
    // always disconnect it whenever the main loop is running. Waiting for the
    // actual disconnect ('end' event) is required to avoid a race where the
    // bzpopmin call is still in flight when the main loop awaits its result.
    if (this.mainLoopRunning) {
      await this.backend.disconnectBlocking(true);
      await this.mainLoopRunning;
    } else {
      reconnect = false;
    }

    reconnect && (await this.backend.reconnectBlocking());
  }

  private async retryIfFailed<T>(
    fn: () => Promise<T>,
    opts: {
      delayInMs: number;
      span?: Span;
      maxRetries?: number;
      onlyEmitError?: boolean;
    },
  ): Promise<T> {
    let retry = 0;
    const maxRetries = opts.maxRetries ?? Infinity;

    do {
      try {
        return await fn();
      } catch (err) {
        opts.span?.recordException((<Error>err).message);

        if (isNotConnectionError(<Error>err)) {
          // Emit error when not paused or closing; optionally swallow (no throw) when opts.onlyEmitError is set.
          if (!this.paused && !this.closing) {
            this.emit('error', <Error>err);
          }

          if (opts.onlyEmitError) {
            return;
          } else {
            throw err;
          }
        } else {
          if (this.closing || this.closed) {
            if (opts.onlyEmitError) {
              return;
            }
            throw err;
          }

          if (opts.delayInMs && !this.closing && !this.closed) {
            await this.delay(opts.delayInMs, this.abortDelayController);
          }

          if (retry + 1 >= maxRetries) {
            // If we've reached max retries, throw the last error
            throw err;
          }
        }
      }
    } while (++retry < maxRetries);
  }

  private async moveStalledJobsToWait() {
    await this.trace<void>(
      SpanKind.INTERNAL,
      'moveStalledJobsToWait',
      this.name,
      async span => {
        const stalled = await this.backend.moveStalledJobsToWait();

        span?.setAttributes({
          [TelemetryAttributes.WorkerId]: this.id,
          [TelemetryAttributes.WorkerName]: this.opts.name,
          [TelemetryAttributes.WorkerStalledJobs]: stalled,
        });

        stalled.forEach((jobId: string) => {
          span?.addEvent('job stalled', {
            [TelemetryAttributes.JobId]: jobId,
          });
          this.emit('stalled', jobId, 'active');
        });
      },
    );
  }

  private moveLimitedBackToWait(
    job: Job<DataType, ResultType, NameType, ProgressType>,
    token: string,
  ) {
    return job.moveToWait(token);
  }
}

